/** Builds the vault's generated index: map, knowledge, tickets and lint. */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { neutralizeScripts } from './core.ts';
import { compare, shown } from './python.ts';
import * as lint from './vault-lint.ts';
import { type Note, asList, load, printed } from './vault-notes.ts';
import { Vault } from './vault.ts';

const INDEX_DIR = 'index';
const GENERATED =
  "Generated by Erebor before and after every run. Don't edit " +
  'it: change the notes and it follows.';
const MAP_INTRO =
  'One line per note. An archived topic is off the dashboard, not out of ' +
  'date: what it decided still holds unless struck through.';
const KNOWLEDGE_INTRO =
  'Every live statement in the areas and topics, one per line, tagged ' +
  'with its kind and its note. Superseded decisions are left out.';
const TICKETS_INTRO =
  'Every ticket and pull request with a note, or that two or more notes ' +
  'mention, and where it comes up.';
const STATUS_ORDER = ['active', 'paused', 'proposed', 'archived'];
const AGENT = 'agent';
const KINDS: Record<string, string> = {
  Facts: 'fact',
  Decisions: 'decision',
  Constraints: 'constraint',
  'Answered questions': 'answered',
  'Open questions': 'open question',
  Gaps: 'gap',
};
const SUPERSEDED = '~~';
// What the map calls the other side of a topic-to-area tie.
const PARTNER_LABEL: Record<string, string> = {
  topics: 'areas',
  areas: 'topics',
};
const SEE_ALSO_LIMIT = 5;
const MIN_MENTIONS = 2;
const ALL_DIGITS = /^[0-9]+$/;
const LINT_ENTRY = '\n- ';

export function links(names: string[]): string {
  return names.map((name) => `[[${name}]]`).join(', ');
}

function count(number: number, noun: string): string {
  return number === 1 ? `${number} ${noun}` : `${number} ${noun}s`;
}

function labelled(label: string, text: string): string {
  return text ? `${label}: ${text}` : '';
}

function joined(parts: string[]): string {
  return parts.filter(Boolean).join(' · ');
}

function section(title: string, lines: string[]): string[] {
  return lines.length > 0 ? [`## ${title}`, '', ...lines, ''] : [];
}

function page(title: string, intro: string, lines: string[]): string {
  return [`# ${title}`, '', GENERATED, intro, '', ...lines].join('\n');
}

/** A topic's areas, or the topics that name an area. */
function partnersOf(vault: Vault, hub: Note): string[] {
  if (hub.folder === 'topics') return asList(hub.meta.get('areas'));
  return vault.topics
    .filter((topic) => asList(topic.meta.get('areas')).includes(hub.name))
    .map((topic) => topic.name);
}

function evidenceOf(vault: Vault, hub: Note): Set<string> {
  return vault.evidence.get(hub.name) ?? new Set();
}

/** Other hubs ranked by the sources they share and the links between. */
function seeAlso(vault: Vault, hub: Note, alreadyShown: string[]): string[] {
  const mine = evidenceOf(vault, hub);
  const scores = new Map<string, number>();
  for (const other of vault.hubs) {
    if (other.name === hub.name || alreadyShown.includes(other.name)) continue;
    const theirs = evidenceOf(vault, other);
    const shared = [...mine].filter((source) => theirs.has(source)).length;
    const linked =
      Number(hub.links.has(other.name)) + Number(other.links.has(hub.name));
    scores.set(other.name, shared + linked);
  }
  return [...scores.keys()]
    .filter((name) => scores.get(name))
    .sort(
      (one, other) =>
        (scores.get(other) ?? 0) - (scores.get(one) ?? 0) ||
        compare(one, other),
    )
    .slice(0, SEE_ALSO_LIMIT);
}

function hubLine(vault: Vault, hub: Note): string {
  const status = shown(hub.meta.get('status'));
  const partners = partnersOf(vault, hub);
  const used = vault.sources.filter(
    (source) =>
      source.meta.get('source') === AGENT && source.links.has(hub.name),
  ).length;
  const parts = [
    shown(hub.meta.get('description')),
    labelled('also', asList(hub.meta.get('aliases')).join(', ')),
    labelled('updated', shown(hub.meta.get('last_updated'))),
    count(evidenceOf(vault, hub).size, 'source'),
    used ? `used ${used}` : '',
    labelled(PARTNER_LABEL[hub.folder], links(partners)),
    labelled('see also', links(seeAlso(vault, hub, partners))),
  ];
  const head = status ? `[[${hub.name}]] — ${status}` : `[[${hub.name}]]`;
  return `- ${head} — ${joined(parts)}`;
}

function personLine(vault: Vault, person: Note): string {
  const seen = vault.sources.filter((source) =>
    vault.peopleIn(source).has(person.name),
  ).length;
  const parts = [
    shown(person.meta.get('role')),
    labelled('also', asList(person.meta.get('aliases')).join(', ')),
    `in ${count(seen, 'source note')}`,
  ];
  const name = printed(person, 'name', person.name);
  return `- [[${person.name}]] — ${name} — ${joined(parts)}`;
}

function statusRank(topic: Note): number {
  const status = topic.meta.get('status');
  return typeof status === 'string'
    ? Math.max(0, STATUS_ORDER.indexOf(status))
    : 0;
}

function renderMap(vault: Vault): string {
  const topics = [...vault.topics].sort(
    (one, other) =>
      statusRank(one) - statusRank(other) || compare(one.name, other.name),
  );
  const dropped = vault.dropped.map(
    (topic) => `- ${topic.name} — ${printed(topic, 'description', '')}`,
  );
  return page('Vault map', MAP_INTRO, [
    ...section('Areas', vault.areas.map((area) => hubLine(vault, area))),
    ...section('Topics', topics.map((topic) => hubLine(vault, topic))),
    ...section('People', vault.people.map((p) => personLine(vault, p))),
    ...section('Dropped topics', dropped),
  ]);
}

function statements(vault: Vault, heading: string): string[] {
  return vault.hubs.flatMap((hub) => {
    const status = printed(hub, 'status', 'active');
    const cite = `[[${hub.name}]]${status === 'active' ? '' : ` (${status})`}`;
    return (hub.sections.get(heading) ?? [])
      .filter((bullet) => !bullet.startsWith(SUPERSEDED))
      .map((bullet) => `- ${KINDS[heading]} · ${cite} · ${bullet}`);
  });
}

function renderKnowledge(vault: Vault): string {
  const lines = Object.keys(KINDS).flatMap((heading) =>
    section(heading, statements(vault, heading)),
  );
  return page('Live knowledge', KNOWLEDGE_INTRO, lines);
}

function ticketNumber(key: string): bigint {
  const number = key.slice(key.lastIndexOf('-') + 1);
  return ALL_DIGITS.test(number) ? BigInt(number) : 0n;
}

function ticketPrefix(key: string): string {
  return key.slice(0, Math.max(0, key.lastIndexOf('-')));
}

function compareTickets(one: string, other: string): number {
  const byNumber = ticketNumber(one) - ticketNumber(other);
  return (
    compare(ticketPrefix(one), ticketPrefix(other)) ||
    Number(byNumber > 0n) - Number(byNumber < 0n) ||
    compare(one, other)
  );
}

function ticketLine(vault: Vault, key: string): string {
  const note = vault.tickets.get(key);
  const mentioned = [...(vault.mentions.get(key) ?? [])].sort(compare);
  const where = labelled('in', links(mentioned));
  if (!note) {
    const label = vault.labels.get(key) ?? key;
    return `- ${label} — ${joined(['no note', where])}`;
  }
  const sourceId = note.meta.get('source_id');
  const parts = [
    shown(note.meta.get('title')),
    sourceId === key ? '' : shown(sourceId),
    labelled('topics', asList(note.meta.get('topics')).join(', ')),
    labelled('areas', asList(note.meta.get('areas')).join(', ')),
    where,
  ];
  return `- [[${key}]] — ${joined(parts)}`;
}

function renderTickets(vault: Vault): string {
  const keys = new Set([...vault.tickets.keys(), ...vault.mentions.keys()]);
  const listed = [...keys].filter(
    (key) =>
      vault.tickets.has(key) ||
      (vault.mentions.get(key)?.size ?? 0) >= MIN_MENTIONS,
  );
  const lines = listed
    .sort(compareTickets)
    .map((key) => ticketLine(vault, key));
  return page('Tickets and pull requests', TICKETS_INTRO, [...lines, '']);
}

/** Every index file's text, by file name. */
export function build(notes: Note[]): Record<string, string> {
  const vault = new Vault(notes);
  return {
    'map.md': renderMap(vault),
    'knowledge.md': renderKnowledge(vault),
    'tickets.md': renderTickets(vault),
    'lint.md': page('Lint', lint.INTRO, lint.render(vault)),
  };
}

// The live index rebuilds often; an untouched file spares Obsidian a reload.
function writeIfChanged(path: string, text: string): void {
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current !== text) writeFileSync(path, text);
}

/** Rewrite the index folder; return how many entries lint lists. */
export function rebuild(vault: string): number {
  const files = build(load(vault));
  const folder = join(vault, INDEX_DIR);
  mkdirSync(folder, { recursive: true });
  for (const [name, text] of Object.entries(files)) {
    writeIfChanged(join(folder, name), neutralizeScripts(text));
  }
  return files['lint.md'].split(LINT_ENTRY).length - 1;
}
